parameters.jsCode:
const items = $input.all();
return items.map(item => {
  const payload = item.json.body || item.json;
  const events = payload.events || [payload];
  const event = events[0] || {};
  const resource = event.resource || {};
  const parent = event.parent || {};
  const now = new Date();
  const dueDate = resource.due_on ? new Date(resource.due_on) : null;
  const isOverdue = dueDate ? dueDate < now && !resource.completed : false;
  return {
    json: {
      taskId: resource.gid || '',
      taskName: resource.name || '',
      assignee: resource.assignee?.name || 'Unassigned',
      assigneeEmail: resource.assignee?.email || '',
      projectName: parent.name || '',
      dueDate: resource.due_on || '',
      isOverdue: isOverdue,
      completed: resource.completed || false,
      status: resource.completed ? 'Completed' : (isOverdue ? 'Overdue' : 'In Progress'),
      notes: (resource.notes || '').substring(0, 300),
      action: event.action || 'updated',
      timestamp: now.toISOString()
    }
  };
});

